const pendingFormRestores=new WeakMap();
function formBusyLabel(form,button){let id=form.id,text=(button?.textContent||"").trim().toLowerCase();if(id==="login-form")return"Signing in...";if(id==="room-form")return text.includes("add room")?"Adding room...":"Saving room...";if(id==="bulk-room-form")return"Adding rooms...";if(id==="building-form")return text.includes("add building")?"Adding building...":"Saving building...";if(id==="schedule-form")return"Adding schedule...";if(id==="planner-form")return"Saving schedules...";if(id==="schedule-edit-form")return"Saving schedule...";if(id==="staff-form")return"Creating account...";if(id==="staff-edit-form")return"Saving account...";if(id==="check-form")return"Saving room check...";return"Saving..."}
