async function api(url,opt){let candidate=pendingActionCandidate;pendingActionCandidate=null;let restore=null,form=candidate?.form;if(candidate&&!form)restore=setButtonBusy(candidate.button,pendingLabel(url,opt,candidate.button));if(form&&!pendingFormRestores.has(form))lockPendingForm(form,candidate.button);try{if(window.roundsSupabaseSetupError)throw Error(window.roundsSupabaseSetupError);if(window.roundsSupabase)return await window.roundsSupabase.api(url,opt);let r=await fetch(url,{credentials:"same-origin",headers:{"Content-Type":"application/json"},...(opt||{})});let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||"Request failed.");return j}catch(error){if(form)releasePendingForm(form);throw error}finally{restore?.()}}
