function showFormError(form,message){if(!form)return;releasePendingForm(form);let error=form.querySelector(".form-error");if(!error){error=document.createElement("div");error.className="form-error";error.setAttribute("role","alert");error.tabIndex=-1;form.prepend(error)}error.textContent=message||"Could not save. Review the form and try again.";error.focus({preventScroll:false})}
function isArchivedRecord(item){return !!item&&(item.archived===true||item.active===false)}
