function deleteFailureMessage(error){let message=String(error?.message||"");if(/completed room checks/i.test(message))return "This account completed room checks. Archive it to preserve check history.";if(/uploaded room-check photos/i.test(message))return "This account has uploaded room-check photos. Archive it to preserve those records.";if(/23503|foreign key|violates.*constraint|constraint.*violat/i.test(message))return "Other records still depend on this item. Archive it instead so check history stays intact.";return message||"The record could not be deleted."}
function recordDisplayName(entity,id,fallback){
  let list=entity==="buildings"?s.data.buildings:entity==="rooms"?s.data.rooms:entity==="schedules"?s.data.schedules:s.data.users,item=list?.find(x=>x.id===id);
  if(!item)return fallback;
  if(entity==="rooms")return "Room "+(item.roomNumber||"")+" · "+(item.name||"Unnamed room");
  if(entity==="schedules")return (item.course||"Schedule")+" · "+(item.instructor||"");
  return item.name||fallback;
}
async function deleteEntity(entity,id,label,button){
  let name=recordDisplayName(entity,id,label);
  if(!await confirmAction("Delete "+name+"?","This permanently removes the "+label+". Existing check history can prevent deletion.","Delete permanently",true))return;
  return withButtonBusy(button,"Deleting "+label.toLowerCase()+".",async()=>{
    try{await api("/api/"+entity+"/"+encodeURIComponent(id),{method:"DELETE"});await load();toast(label+" deleted","The record was permanently removed.")}
    catch(error){toast("Could not delete "+label.toLowerCase(),deleteFailureMessage(error),"error")}
  })
}
