function labelStatus(x){return({due:"Due now",overdue:"Overdue",checked:"Checked",issue:"Issue open",progress:"In progress",upcoming:"Upcoming",resolved:"Resolved"})[x]||x}
const tasks=()=>(s.data?.rounds||[]).filter(t=>!isArchivedLocation(s.data.rooms.find(r=>r.id===t.room.id)));
function statusSignature(){return tasks().map(t=>t.id+":"+statusOf(t)).join("|")}
