function historyRow(x){let c=x.check||{},label=(value,dict)=>dict[value]||"Not recorded",when=new Intl.DateTimeFormat("en-PH",{timeZone:"Asia/Manila",month:"short",day:"numeric",hour:"numeric",minute:"2-digit"}).format(new Date(x.completedAt)),state=x.issueStatus==="open"?"issue":x.issueStatus==="resolved"?"resolved":"checked";return '<div class="history-row"><div class="history-when">'+esc(when)+'</div><div class="history-room"><strong>'+esc(x.room.name)+' · Room '+esc(x.room.roomNumber)+'</strong><span>'+esc(x.building.name)+' · '+esc(x.schedule.course)+' · '+esc(x.schedule.instructor)+'</span></div><div class="history-observations"><span>PC '+esc(label(c.pcInUse,{yes:"in use",no:"not used",unknown:"not checked"}))+'</span><span>HDMI '+esc(label(c.laptopHdmi,{yes:"connected",no:"not connected",unknown:"not checked"}))+'</span><span>Display '+esc(label(c.display,{normal:"normal",attention:"needs attention",damaged:"damaged",unknown:"not checked"}))+'</span></div><div class="history-person">'+esc(x.completer?.name||"Former account")+'</div><span class="status '+state+'">'+(state==="issue"?"Issue open":state==="resolved"?"Resolved":"Checked")+'</span><button class="button small subtle" data-action="history-view" data-id="'+x.id+'">View</button></div>'}
