function dialog(title,desc,body,footer,wide){
  let d=$("#dialog"),wasOpen=d.open;
  d.className="dialog"+(wide?" wide":"");
  d.setAttribute("aria-labelledby","dialog-title");
  d.setAttribute("aria-describedby","dialog-description");
  d.innerHTML='<div class="dialog-head"><div><h2 id="dialog-title" class="dialog-title">'+esc(title)+'</h2><p id="dialog-description" class="dialog-description">'+esc(desc)+'</p></div><button class="icon-button" data-action="close" aria-label="Close">'+ico("close")+'</button></div><div class="dialog-body">'+body+'</div><div class="dialog-foot">'+footer+"</div>";
  d.addEventListener("close",()=>{d.querySelectorAll("form[data-pending=true]").forEach(releasePendingForm);if(s.refreshPending||s.loadedDate!==today())queueRefresh()},{once:true});
  if(!wasOpen){
    d.showModal();
    requestAnimationFrame(()=>{
      let danger=d.querySelector(".dialog-foot .button.delete");
      let target=danger?d.querySelector('.dialog-foot [data-action="close"]'):d.querySelector('.dialog-body form input:not([type="hidden"]):not([disabled]), .dialog-body form select:not([disabled]), .dialog-body form textarea:not([disabled])')||d.querySelector(".dialog-foot button:not([disabled])")||d.querySelector('.dialog-head [data-action="close"]');
      if(d.open)target?.focus({preventScroll:true});
    });
  }
}
