function parseCsv(text){let rows=[],row=[],cell="",quoted=false,source=String(text||"").replace(/^\uFEFF/,"");for(let i=0;i<source.length;i++){let c=source[i];if(quoted){if(c==='"'&&source[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===","){row.push(cell);cell=""}else if(c==="\n"){row.push(cell.replace(/\r$/, ""));rows.push(row);row=[];cell=""}else cell+=c}if(cell||row.length){row.push(cell.replace(/\r$/, ""));rows.push(row)}let headers=rows.shift()||[];return rows.map((r,index)=>({...Object.fromEntries(headers.map((h,i)=>[h,r[i]||""])),sourceRow:index+2}))}
